window.TianSemiNetworkEngineeringTranslations = networkEngineeringTranslations;

document.addEventListener("DOMContentLoaded", () => {
  const root = document.querySelector("[data-network-engineering-lesson]");
  if (!root) return;

  const translations = networkEngineeringTranslations;
  const pageMeta = {
    fr: {
      title: "HCIA-Datacom : ingénierie réseau et métier d’ingénieur réseau — TianSemi",
      description: "Comprendre le cycle de l’ingénierie réseau, les responsabilités et compétences de l’ingénieur réseau, avec six flashcards HCIA-Datacom."
    },
    en: {
      title: "HCIA-Datacom: Network Engineering and the Network Engineer Profession — TianSemi",
      description: "Understand the network engineering lifecycle, the responsibilities and capabilities of a network engineer, with six HCIA-Datacom flashcards."
    }
  };

  const cardCopy = {
    fr: { show: "Afficher la réponse", hide: "Masquer la réponse" },
    en: { show: "Show answer", hide: "Hide answer" }
  };

  const originalText = new WeakMap();
  const originalAttributes = new WeakMap();
  const cards = [...root.querySelectorAll("[data-revision-card]")];
  const revealAll = root.querySelector("[data-reveal-all]");
  const reset = root.querySelector("[data-reset-cards]");

  const normalize = (value) => String(value).replace(/\s+/g, " ").trim();
  const getLanguage = () => document.documentElement.lang === "en" ? "en" : "fr";

  function translateTextNodes(language) {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        return normalize(node.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
      }
    });
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);

    nodes.forEach((node) => {
      if (!originalText.has(node)) originalText.set(node, node.nodeValue);
      const original = originalText.get(node);
      const key = normalize(original);
      const translated = language === "en" ? translations[key] || key : key;
      const leading = original.match(/^\s*/)?.[0] || "";
      const trailing = original.match(/\s*$/)?.[0] || "";
      node.nodeValue = `${leading}${translated}${trailing}`;
    });
  }

  function translateAttributes(language) {
    root.querySelectorAll("[alt], [aria-label]").forEach((element) => {
      if (!originalAttributes.has(element)) originalAttributes.set(element, {});
      const originals = originalAttributes.get(element);
      ["alt", "aria-label"].forEach((attribute) => {
        if (!element.hasAttribute(attribute)) return;
        if (!(attribute in originals)) originals[attribute] = element.getAttribute(attribute);
        const original = originals[attribute];
        element.setAttribute(attribute, language === "en" ? translations[normalize(original)] || original : original);
      });
    });
  }

  function updateImages(language) {
    root.querySelectorAll("img[data-src-fr][data-src-en]").forEach((image) => {
      image.setAttribute("src", language === "en" ? image.dataset.srcEn : image.dataset.srcFr);
    });
  }

  function updateMetadata(language) {
    const meta = pageMeta[language];
    document.title = meta.title;
    const description = document.querySelector('meta[name="description"]');
    if (description) description.setAttribute("content", meta.description);
  }

  function setCard(card, open, language = getLanguage()) {
    const trigger = card.querySelector(".revision-card__trigger");
    const answer = card.querySelector(".revision-card__answer");
    const hint = card.querySelector(".revision-card__hint");
    card.dataset.open = String(open);
    trigger.setAttribute("aria-expanded", String(open));
    answer.hidden = !open;
    hint.textContent = open ? cardCopy[language].hide : cardCopy[language].show;
  }

  function applyLessonLanguage(language = getLanguage()) {
    translateTextNodes(language);
    translateAttributes(language);
    updateImages(language);
    updateMetadata(language);
    cards.forEach((card) => setCard(card, card.dataset.open === "true", language));
  }

  function synchronizeLessonLanguage(language = getLanguage()) {
    applyLessonLanguage(language);
    window.setTimeout(() => applyLessonLanguage(language), 0);
  }

  cards.forEach((card) => {
    const trigger = card.querySelector(".revision-card__trigger");
    setCard(card, false);
    trigger.addEventListener("click", () => setCard(card, trigger.getAttribute("aria-expanded") !== "true"));
  });

  revealAll?.addEventListener("click", () => cards.forEach((card) => setCard(card, true)));
  reset?.addEventListener("click", () => {
    cards.forEach((card) => setCard(card, false));
    cards[0]?.querySelector(".revision-card__trigger")?.focus();
  });

  document.addEventListener("tiansemi:i18n", (event) => {
    synchronizeLessonLanguage(event.detail?.lang === "en" ? "en" : "fr");
  });

  synchronizeLessonLanguage(getLanguage());
});
